diffs.replacement:
export enum SampleType {
  URINE = 'Urine (ECBU)',
  BLOOD = 'Blood Culture',
  PUS = 'Pus/Wound',
  CSF = 'CSF',
  STOOL = 'Stool',
  RESPIRATORY = 'Respiratory',
  OTHER = 'Other'
}

export enum GramStatus {
  UNKNOWN = 'Unknown',
  GPC = 'Gram Positive Cocci',
  GNB = 'Gram Negative Bacilli',
  GPB = 'Gram Positive Bacilli',
  GNC = 'Gram Negative Cocci',
  YEAST = 'Yeast'
}

export enum TestType {
  CATALASE = 'Catalase',
  COAGULASE = 'Coagulase',
  OXIDASE = 'Oxidase',
  KLIGLER = 'Kligler (Glu/Lac/Gas/H2S)',
  MANNITOL = 'Mannitol Motility',
  UREA_INDOLE = 'Urea-Indole',
  CITRATE = 'Citrate (Simmons)',
  VITEK = 'Vitek Automaton',
  API_20E = 'API 20E',
  API_STAPH = 'API Staph'
}

export enum TestResultValue {
  PENDING = 'Pending',
  POSITIVE = 'Positive (+)',
  NEGATIVE = 'Negative (-)',
  INDETERMINATE = 'Indeterminate',
  // Specific for Kligler
  ALK_ACID = 'K/A (Red/Yellow)',
  ACID_ACID = 'A/A (Yellow/Yellow)',
  ALK_ALK = 'K/K (Red/Red)',
}

export interface TestEntry {
  id: string;
  type: TestType;
  result: TestResultValue;
  notes?: string;
  timestamp: number;
}

export interface PlateObservation {
  id: string;
  media: string; // e.g. "Blood Agar", "MacConkey"
  morphology: string; // e.g. "S-type, creamy, beta-hemolysis"
  growth: 'No Growth' | 'Scanty' | 'Moderate' | 'Heavy';
  imageUrl?: string;
}

export interface Sample {
  id: string;
  patientId: string;
  type: SampleType;
  collectionDate: string;
  gramStatus: GramStatus;
  plates: PlateObservation[];
  tests: TestEntry[];
  aiAnalysis?: string;
  status: 'Processing' | 'Ready for ID' | 'Completed';
}

import { SampleType, GramStatus, TestType, TestResultValue } from './types';

export const MEDIA_TYPES = [
  'Blood Agar',
  'Chocolate Agar',
  'MacConkey Agar',
  'CLED Agar',
  'Mannitol Salt Agar',
  'Sabouraud Dextrose Agar',
  'Hektoen Enteric Agar',
  'Mueller-Hinton'
];

export const INITIAL_TESTS_GNB = [
  TestType.OXIDASE
];

export const INITIAL_TESTS_GPC = [
  TestType.CATALASE
];

export const MINI_GALLERIE = [
  TestType.KLIGLER,
  TestType.CITRATE,
  TestType.MANNITOL,
  TestType.UREA_INDOLE
];

export const TEST_OPTIONS = {
  [TestType.OXIDASE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.CATALASE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.COAGULASE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.UREA_INDOLE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.CITRATE]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.MANNITOL]: [TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.KLIGLER]: [TestResultValue.ALK_ACID, TestResultValue.ACID_ACID, TestResultValue.ALK_ALK],
  [TestType.VITEK]: [TestResultValue.PENDING, TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.API_20E]: [TestResultValue.PENDING, TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
  [TestType.API_STAPH]: [TestResultValue.PENDING, TestResultValue.POSITIVE, TestResultValue.NEGATIVE],
};

export const MOCK_SAMPLES = [
  {
    id: 'S-2024-001',
    patientId: 'P-8842',
    type: SampleType.URINE,
    collectionDate: new Date().toISOString(),
    gramStatus: GramStatus.GNB,
    plates: [
      { id: '1', media: 'CLED Agar', morphology: 'Large yellow opaque colonies (Lactose fermenter)', growth: 'Heavy' }
    ],
    tests: [],
    status: 'Processing'
  }
];

import React, { useState, useEffect } from 'react';
import { Sample, GramStatus, TestType, TestResultValue, PlateObservation, TestEntry } from '../types';
import { MEDIA_TYPES, TEST_OPTIONS, MINI_GALLERIE } from '../constants';
import { analyzeBacteriologyCase } from '../services/geminiService';
import TestTube from './TestTube';
import { Plus, Trash2, Microscope, Wand2, FlaskConical, ArrowRight, Loader2, Save, Activity, CheckCircle2 } from 'lucide-react';

interface WorkBenchProps {
  sample: Sample;
  onUpdateSample: (updated: Sample) => void;
}

const WorkBench: React.FC<WorkBenchProps> = ({ sample, onUpdateSample }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [activeTab, setActiveTab] = useState<'plates' | 'biochem' | 'id'>('plates');

  // Local state for forms
  const [newPlateMedia, setNewPlateMedia] = useState(MEDIA_TYPES[0]);
  const [newPlateMorph, setNewPlateMorph] = useState('');
  const [newPlateGrowth, setNewPlateGrowth] = useState<PlateObservation['growth']>('Moderate');

  const updateGram = (status: GramStatus) => {
    onUpdateSample({ ...sample, gramStatus: status });
  };

  const addPlateObservation = () => {
    if (!newPlateMorph) return;
    const newPlate: PlateObservation = {
      id: Date.now().toString(),
      media: newPlateMedia,
      morphology: newPlateMorph,
      growth: newPlateGrowth
    };
    onUpdateSample({ ...sample, plates: [...sample.plates, newPlate] });
    setNewPlateMorph('');
  };

  const removePlate = (id: string) => {
    onUpdateSample({ ...sample, plates: sample.plates.filter(p => p.id !== id) });
  };

  const setTestResult = (type: TestType, result: TestResultValue) => {
    const existing = sample.tests.find(t => t.type === type);
    let newTests = [...sample.tests];

    if (existing) {
      newTests = newTests.map(t => t.type === type ? { ...t, result } : t);
    } else {
      newTests.push({
        id: Date.now().toString(),
        type,
        result,
        timestamp: Date.now()
      });
    }
    onUpdateSample({ ...sample, tests: newTests });
  };

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
    const advice = await analyzeBacteriologyCase(sample);
    onUpdateSample({ ...sample, aiAnalysis: advice });
    setIsAnalyzing(false);
    setActiveTab('id'); // Switch to results tab
  };

  const handleVitekSetup = () => {
    // Check if already exists to prevent duplicates (though we could allow re-runs)
    if (sample.tests.some(t => t.type === TestType.VITEK)) return;

    const newTest: TestEntry = {
      id: Date.now().toString(),
      type: TestType.VITEK,
      result: TestResultValue.PENDING,
      timestamp: Date.now()
    };

    onUpdateSample({
      ...sample,
      status: 'Ready for ID',
      tests: [...sample.tests, newTest]
    });
  };

  const handleAPISetup = () => {
    // Determine appropriate API strip based on Gram status
    const type = sample.gramStatus === GramStatus.GPC ? TestType.API_STAPH : TestType.API_20E;

    if (sample.tests.some(t => t.type === type)) return;

    const newTest: TestEntry = {
      id: Date.now().toString(),
      type: type,
      result: TestResultValue.PENDING,
      timestamp: Date.now()
    };

    onUpdateSample({
      ...sample,
      status: 'Ready for ID',
      tests: [...sample.tests, newTest]
    });
  };

  const hasVitek = sample.tests.some(t => t.type === TestType.VITEK);
  const hasAPI = sample.tests.some(t => t.type === TestType.API_20E || t.type === TestType.API_STAPH);

  // Logic for suggesting tests
  const getSuggestedTests = () => {
    const suggestions: TestType[] = [];
    const hasTest = (t: TestType) => sample.tests.some(test => test.type === t);

    if (sample.gramStatus === GramStatus.GNB) {
      if (!hasTest(TestType.OXIDASE)) suggestions.push(TestType.OXIDASE);
      else {
        const ox = sample.tests.find(t => t.type === TestType.OXIDASE);
        if (ox?.result === TestResultValue.NEGATIVE) {
          // If Oxidase -, suggest Mini Gallerie
          MINI_GALLERIE.forEach(t => {
            if (!hasTest(t)) suggestions.push(t);
          });
        }
      }
    } else if (sample.gramStatus === GramStatus.GPC) {
      if (!hasTest(TestType.CATALASE)) suggestions.push(TestType.CATALASE);
      else {
        const cat = sample.tests.find(t => t.type === TestType.CATALASE);
        if (cat?.result === TestResultValue.POSITIVE && !hasTest(TestType.COAGULASE)) {
          suggestions.push(TestType.COAGULASE);
        }
      }
    }
    return suggestions;
  };

  const suggestedTests = getSuggestedTests();

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Header */}
      <div className="bg-slate-50 border-b border-slate-200 p-4 flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <Microscope className="text-teal-600" />
            Workspace: <span className="font-mono text-teal-700">{sample.id}</span>
          </h2>
          <p className="text-sm text-slate-500">{sample.type} | {sample.collectionDate.split('T')[0]}</p>
        </div>
        <div className="flex space-x-2">
           <button 
             onClick={handleAIAnalysis}
             className="flex items-center gap-2 bg-gradient-to-r from-violet-600 to-indigo-600 text-white px-4 py-2 rounded-lg hover:shadow-lg hover:scale-105 transition-all text-sm font-medium disabled:opacity-70"
             disabled={isAnalyzing}
           >
             {isAnalyzing ? <Loader2 className="animate-spin w-4 h-4"/> : <Wand2 className="w-4 h-4" />}
             AI Analysis
           </button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200 bg-white sticky top-0 z-10">
        <button 
          onClick={() => setActiveTab('plates')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'plates' ? 'border-teal-500 text-teal-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          1. Plate Reading & Gram
        </button>
        <button 
          onClick={() => setActiveTab('biochem')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'biochem' ? 'border-teal-500 text-teal-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          2. Biochemical Tests
        </button>
        <button 
          onClick={() => setActiveTab('id')}
          className={`px-6 py-3 text-sm font-medium border-b-2 transition-colors ${activeTab === 'id' ? 'border-teal-500 text-teal-700' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
        >
          3. Identification & Summary
        </button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto p-6 bg-slate-50/50">

        {/* TAB 1: PLATES */}
        {activeTab === 'plates' && (
          <div className="space-y-6 max-w-4xl mx-auto">

            {/* Gram Stain Section */}
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold text-slate-800 mb-3 flex items-center gap-2">
                <div className="w-6 h-6 rounded bg-purple-100 text-purple-600 flex items-center justify-center font-bold text-xs">G</div>
                Gram Stain Status
              </h3>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {Object.values(GramStatus).map((status) => (
                  <button
                    key={status}
                    onClick={() => updateGram(status as GramStatus)}
                    className={`px-3 py-2 text-sm rounded-lg border transition-all text-left ${
                      sample.gramStatus === status 
                        ? 'bg-purple-50 border-purple-500 text-purple-700 ring-1 ring-purple-500' 
                        : 'bg-white border-slate-200 text-slate-600 hover:border-purple-300'
                    }`}
                  >
                    {status}
                  </button>
                ))}
              </div>
            </div>

            {/* Plate List */}
            <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold text-slate-800 mb-4 flex items-center gap-2">
                 <div className="w-6 h-6 rounded bg-teal-100 text-teal-600 flex items-center justify-center font-bold text-xs">P</div>
                 Observed Plates
              </h3>

              <div className="space-y-3 mb-6">
                {sample.plates.map(plate => (
                  <div key={plate.id} className="flex items-start justify-between p-3 bg-slate-50 rounded-lg border border-slate-100">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-semibold text-slate-700">{plate.media}</span>
                        <span className={`text-xs px-2 py-0.5 rounded-full ${
                          plate.growth === 'Heavy' ? 'bg-red-100 text-red-700' : 'bg-green-100 text-green-700'
                        }`}>{plate.growth}</span>
                      </div>
                      <p className="text-sm text-slate-600 mt-1">{plate.morphology}</p>
                    </div>
                    <button onClick={() => removePlate(plate.id)} className="text-slate-400 hover:text-red-500">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                ))}
                {sample.plates.length === 0 && <p className="text-sm text-slate-400 italic">No plates recorded yet.</p>}
              </div>

              {/* Add New Plate Form */}
              <div className="bg-teal-50/50 p-4 rounded-lg border border-teal-100">
                <h4 className="text-sm font-semibold text-teal-800 mb-3">Add Observation</h4>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-3">
                  <select 
                    value={newPlateMedia}
                    onChange={(e) => setNewPlateMedia(e.target.value)}
                    className="p-2 rounded border border-slate-300 text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                  >
                    {MEDIA_TYPES.map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                  <select
                    value={newPlateGrowth}
                    onChange={(e) => setNewPlateGrowth(e.target.value as any)}
                    className="p-2 rounded border border-slate-300 text-sm focus:ring-2 focus:ring-teal-500 outline-none"
                  >
                    {['No Growth', 'Scanty', 'Moderate', 'Heavy'].map(g => <option key={g} value={g}>{g}</option>)}
                  </select>
                </div>
                <textarea
                  placeholder="Describe colony morphology (size, color, hemolysis, smell, lactose ferm...)"
                  value={newPlateMorph}
                  onChange={(e) => setNewPlateMorph(e.target.value)}
                  className="w-full p-2 rounded border border-slate-300 text-sm mb-3 focus:ring-2 focus:ring-teal-500 outline-none h-20 resize-none"
                />
                <button 
                  onClick={addPlateObservation}
                  className="w-full bg-teal-600 text-white py-2 rounded-lg hover:bg-teal-700 transition-colors flex items-center justify-center gap-2 text-sm font-medium"
                >
                  <Plus className="w-4 h-4" /> Add Plate Reading
                </button>
              </div>
            </div>

            <div className="flex justify-end">
              <button 
                onClick={() => setActiveTab('biochem')}
                className="flex items-center gap-2 bg-slate-800 text-white px-6 py-2 rounded-lg hover:bg-slate-700"
              >
                Proceed to Tests <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        )}

        {/* TAB 2: BIOCHEM */}
        {activeTab === 'biochem' && (
          <div className="space-y-8 max-w-5xl mx-auto">

            {/* Suggested Workflow */}
            <div className="bg-blue-50 p-4 rounded-xl border border-blue-100">
              <h3 className="font-semibold text-blue-800 mb-2 flex items-center gap-2">
                <Activity className="w-5 h-5" /> Recommended Follow-up
              </h3>
              <p className="text-sm text-blue-700 mb-3">
                Based on <strong>{sample.gramStatus}</strong>, performing the following tests is recommended:
              </p>
              <div className="flex flex-wrap gap-2">
                {suggestedTests.length > 0 ? suggestedTests.map(t => (
                  <span key={t} className="px-3 py-1 bg-white text-blue-600 text-xs font-bold border border-blue-200 rounded-full shadow-sm animate-pulse">
                    {t}
                  </span>
                )) : <span className="text-sm italic text-blue-500">Please complete Gram stain first or check logic.</span>}
              </div>
            </div>

            {/* Test Bench Visualization */}
            <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
              <h3 className="font-semibold text-slate-800 mb-6 border-b pb-2">Bench Tests (Click to Toggle Result)</h3>

              {/* Flex container for tubes */}
              <div className="flex flex-wrap gap-8 justify-center items-end min-h-[140px]">
                {/* Always show relevant tests or already added tests */}
                {Array.from(new Set([...suggestedTests, ...sample.tests.map(t => t.type)])).map(testType => {
                  const existingTest = sample.tests.find(t => t.type === testType);
                  const currentResult = existingTest ? existingTest.result : TestResultValue.PENDING;

                  return (
                    <div key={testType} className="flex flex-col items-center gap-2">
                       <TestTube 
                          type={testType} 
                          result={currentResult}
                          onClick={() => {
                            // Cycle through options
                            const options = TEST_OPTIONS[testType] || [];
                            const currIdx = options.indexOf(currentResult);
                            const nextResult = currIdx === -1 ? options[0] : options[(currIdx + 1) % options.length];
                            setTestResult(testType, nextResult);
                          }} 
                       />

                       {/* Dropdown fallback/override */}
                       <select 
                        className="text-[10px] w-24 p-1 border rounded bg-slate-50"
                        value={currentResult}
                        onChange={(e) => setTestResult(testType, e.target.value as TestResultValue)}
                       >
                         <option value={TestResultValue.PENDING}>Pending</option>
                         {TEST_OPTIONS[testType]?.map(opt => (
                           <option key={opt} value={opt}>{opt}</option>
                         ))}
                       </select>
                    </div>
                  );
                })}

                {/* Button to manually add other tests if logic misses them */}
                <div className="relative group">
                   <button className="h-24 w-16 border-2 border-dashed border-slate-300 rounded-lg flex flex-col items-center justify-center text-slate-400 hover:border-teal-400 hover:text-teal-500 transition-colors">
                     <Plus className="w-6 h-6" />
                     <span className="text-xs mt-1">Add</span>
                   </button>
                   <div className="absolute top-full mt-2 left-0 w-48 bg-white shadow-xl rounded-lg border border-slate-100 hidden group-hover:block p-2 z-50">
                      {Object.values(TestType).map(t => (
                        <button 
                          key={t}
                          onClick={() => setTestResult(t as TestType, TestResultValue.PENDING)}
                          className="block w-full text-left text-xs p-2 hover:bg-slate-50 rounded"
                        >
                          {t}
                        </button>
                      ))}
                   </div>
                </div>
              </div>
            </div>

             <div className="flex justify-between">
              <button 
                onClick={() => setActiveTab('plates')}
                className="text-slate-500 hover:text-slate-800 text-sm font-medium"
              >
                Back
              </button>
              <button 
                onClick={() => {
                  setActiveTab('id');
                  handleAIAnalysis();
                }}
                className="flex items-center gap-2 bg-teal-600 text-white px-6 py-2 rounded-lg hover:bg-teal-700 shadow-md transition-all"
              >
                 <Wand2 className="w-4 h-4" /> Analyze & Identify
              </button>
            </div>
          </div>
        )}

        {/* TAB 3: IDENTIFICATION */}
        {activeTab === 'id' && (
          <div className="max-w-4xl mx-auto space-y-6">

            {/* AI Result Card */}
            <div className="bg-white rounded-xl border border-indigo-100 shadow-lg overflow-hidden">
               <div className="bg-gradient-to-r from-indigo-50 to-white p-4 border-b border-indigo-100 flex justify-between items-center">
                 <h3 className="font-bold text-indigo-900 flex items-center gap-2">
                   <Wand2 className="w-5 h-5 text-indigo-600" />
                   AI Bacteriologist Interpretation
                 </h3>
                 <span className="text-xs text-indigo-400">Powered by Gemini 2.5 Flash</span>
               </div>
               <div className="p-6 text-slate-700 leading-relaxed text-sm whitespace-pre-wrap">
                 {sample.aiAnalysis ? sample.aiAnalysis : (
                   <div className="text-center py-8 text-slate-400">
                     No analysis generated yet. Click "Analyze" to get expert advice.
                   </div>
                 )}
               </div>
            </div>

            {/* Action Buttons */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {/* VITEK CARD */}
               <div className={`p-4 rounded-xl border transition-all ${
                 hasVitek 
                   ? 'bg-green-100 border-green-300' 
                   : 'bg-green-50 border-green-200 hover:shadow-md'
               }`}>
                  <div className="flex justify-between items-start">
                    <h4 className="font-bold text-green-800 mb-2">Ready for Vitek?</h4>
                    {hasVitek && <CheckCircle2 className="w-5 h-5 text-green-600" />}
                  </div>
                  <p className="text-xs text-green-700 mb-3">If the orientation matches, prepare the suspension.</p>
                  <button 
                    onClick={handleVitekSetup}
                    disabled={hasVitek}
                    className={`w-full py-2 rounded-lg text-sm font-medium transition-colors ${
                      hasVitek 
                        ? 'bg-green-200 text-green-800 cursor-not-allowed'
                        : 'bg-green-600 text-white hover:bg-green-700'
                    }`}
                  >
                    {hasVitek ? 'Vitek ID Logged' : 'Mark Ready for Vitek ID'}
                  </button>
               </div>

               {/* API GALLERY CARD */}
               <div className={`p-4 rounded-xl border transition-all ${
                 hasAPI 
                   ? 'bg-yellow-100 border-yellow-300' 
                   : 'bg-yellow-50 border-yellow-200 hover:shadow-md'
               }`}>
                  <div className="flex justify-between items-start">
                    <h4 className="font-bold text-yellow-800 mb-2">Need API Gallery?</h4>
                    {hasAPI && <CheckCircle2 className="w-5 h-5 text-yellow-600" />}
                  </div>
                  <p className="text-xs text-yellow-700 mb-3">
                    {sample.gramStatus === GramStatus.GPC ? 'API Staph' : 'API 20E (Entero)'} depending on orientation.
                  </p>
                  <button 
                    onClick={handleAPISetup}
                    disabled={hasAPI}
                    className={`w-full py-2 rounded-lg text-sm font-medium transition-colors ${
                      hasAPI 
                        ? 'bg-yellow-200 text-yellow-800 cursor-not-allowed'
                        : 'bg-yellow-500 text-white hover:bg-yellow-600'
                    }`}
                  >
                    {hasAPI ? 'API Setup Logged' : 'Log API Setup'}
                  </button>
               </div>
            </div>

             <div className="flex justify-start">
              <button 
                onClick={() => setActiveTab('biochem')}
                className="text-slate-500 hover:text-slate-800 text-sm font-medium"
              >
                Back to Tests
              </button>
            </div>
          </div>
        )}

      </div>
    </div>
  );
};

export default WorkBench;

payload.text:
**Refining Button Functionality**

I'm now delving into the "Ready for Vitek?" and "Need API Gallery?" buttons within the `WorkBench` component. My focus is on fleshing out their intended behavior. It looks like these buttons are presently placeholders, or perhaps they have incomplete handlers. I'm aiming to understand the desired user flow and the backend interactions necessary for them to function correctly. The goal is to make them fully operational and intuitive for the user.


**Analyzing Button Actions**

I've been examining the intended behaviors for both buttons. "Ready for Vitek?" triggers suspension preparation and status updates, including a 'Vitek' test entry.  "Need API Gallery?" now conditional on Gram status, initiates either an "API 20E" or "API Staph" setup and logs this action. I'm focusing on ensuring these actions correctly reflect the user's expected workflow, aiming for seamless integration within the existing application.


**Reviewing API Integration**

