export enum SampleType {
  URINE = 'Urine (ECBU)',
  BLOOD = 'Blood Culture',
  PUS = 'Pus/Wound',
  CSF = 'CSF',
  STOOL = 'Stool',
  RESPIRATORY = 'Respiratory',
  OTHER = 'Other'
}

export enum GramStatus {
  UNKNOWN = 'Unknown',
  GPC = 'Gram Positive Cocci',
  GNB = 'Gram Negative Bacilli',
  GPB = 'Gram Positive Bacilli',
  GNC = 'Gram Negative Cocci',
  YEAST = 'Yeast'
}

export enum TestType {
  CATALASE = 'Catalase',
  COAGULASE = 'Coagulase',
  OXIDASE = 'Oxidase',
  KLIGLER = 'Kligler (Glu/Lac/Gas/H2S)',
  MANNITOL = 'Mannitol Motility',
  UREA_INDOLE = 'Urea-Indole',
  CITRATE = 'Citrate (Simmons)',
  VITEK = 'Vitek Automaton',
  API_20E = 'API 20E',
  API_STAPH = 'API Staph'
}

export enum TestResultValue {
  PENDING = 'Pending',
  POSITIVE = 'Positive (+)',
  NEGATIVE = 'Negative (-)',
  INDETERMINATE = 'Indeterminate',
  // Specific for Kligler
  ALK_ACID = 'K/A (Red/Yellow)',
  ACID_ACID = 'A/A (Yellow/Yellow)',
  ALK_ALK = 'K/K (Red/Red)',
}

export interface TestEntry {
  id: string;
  type: TestType;
  result: TestResultValue;
  notes?: string;
  timestamp: number;
  gas?: boolean;
  h2s?: boolean;
}

export interface PlateObservation {
  id: string;
  media: string; // e.g. "Blood Agar", "MacConkey"
  morphology: string; // e.g. "S-type, creamy, beta-hemolysis"
  growth: 'No Growth' | 'Scanty' | 'Moderate' | 'Heavy';
  smell?: string; // e.g. "Grape-like", "Putrid"
  imageUrl?: string;
}

export interface Sample {
  id: string;
  patientId: string;
  type: SampleType;
  collectionDate: string;
  gramStatus: GramStatus;
  plates: PlateObservation[];
  tests: TestEntry[];
  aiAnalysis?: string;
  status: 'Processing' | 'Ready for ID' | 'Completed';
}

import React from 'react';
import { TestType, TestResultValue } from '../types';

interface TestTubeProps {
  type: TestType;
  result: TestResultValue;
  onClick: () => void;
  gas?: boolean;
  h2s?: boolean;
}

const TestTube: React.FC<TestTubeProps> = ({ type, result, onClick, gas, h2s }) => {

  const getColors = () => {
    if (result === TestResultValue.PENDING) return 'bg-gray-200 border-gray-300 text-gray-400';

    // Kligler Logic
    if (type === TestType.KLIGLER) {
      let fromColor = '';
      let toColor = '';
      let borderColor = 'border-red-600';
      let textColor = 'text-white';

      // Top (Slant)
      if (result === TestResultValue.ACID_ACID) {
        fromColor = 'from-yellow-400';
        borderColor = 'border-yellow-500';
        textColor = 'text-yellow-900';
      } else if (result === TestResultValue.ALK_ACID || result === TestResultValue.ALK_ALK) {
        fromColor = 'from-red-500';
      } else {
        // Pending or invalid
        return 'bg-gray-200 border-gray-300 text-gray-400';
      }

      // Bottom (Butt)
      if (h2s) {
        toColor = 'to-slate-900'; // Black for H2S
        textColor = 'text-white'; // Ensure text is visible on black
      } else {
        if (result === TestResultValue.ACID_ACID || result === TestResultValue.ALK_ACID) {
          toColor = 'to-yellow-400';
        } else {
          toColor = 'to-red-500';
        }
      }

      // Override text color if A/A and no H2S (Yellow background needs dark text)
      if (result === TestResultValue.ACID_ACID && !h2s) {
        textColor = 'text-yellow-900';
      }

      return `bg-gradient-to-b ${fromColor} ${toColor} ${borderColor} ${textColor}`;
    }

    // Urea Indole
    if (type === TestType.UREA_INDOLE) {
      if (result === TestResultValue.POSITIVE) return 'bg-pink-500 border-pink-600 text-white'; // Urease +
      if (result === TestResultValue.NEGATIVE) return 'bg-yellow-100 border-yellow-300 text-yellow-800'; // Urease -
    }

    // Citrate
    if (type === TestType.CITRATE) {
      if (result === TestResultValue.POSITIVE) return 'bg-blue-600 border-blue-700 text-white'; // Citrate + (Blue)
      if (result === TestResultValue.NEGATIVE) return 'bg-green-500 border-green-600 text-white'; // Citrate - (Green)
    }

    // Standard Positive/Negative for others
    if (result === TestResultValue.POSITIVE) return 'bg-teal-500 border-teal-600 text-white';
    if (result === TestResultValue.NEGATIVE) return 'bg-rose-100 border-rose-300 text-rose-800';

    return 'bg-slate-100 border-slate-300 text-slate-600';
  };

  return (
    <div 
      onClick={onClick}
      className={`relative h-24 w-16 rounded-b-2xl rounded-t-md border-2 flex flex-col items-center justify-end p-2 cursor-pointer transition-transform hover:scale-105 shadow-sm ${getColors()}`}
    >
      <div className="absolute top-[-10px] w-full text-center">
         <span className="text-[10px] uppercase font-bold tracking-tighter text-slate-500 bg-white/80 px-1 rounded shadow-sm border border-slate-200">
          {type.split(' ')[0]}
         </span>
      </div>

      {/* Visual Indicators for Gas and H2S */}
      {gas && (
        <div className="absolute top-8 right-1 bg-white/30 backdrop-blur-sm rounded-full w-5 h-5 flex items-center justify-center border border-white/50 shadow-sm" title="Gas Production">
          <span className="text-[9px] font-bold">G</span>
        </div>
      )}

      {h2s && (
        <div className="absolute bottom-6 left-1 text-[8px] font-bold text-white/90 bg-black/20 px-1 rounded" title="H2S Production">
          H2S
        </div>
      )}

      <span className="text-xs font-bold text-center leading-tight z-10">
        {result === TestResultValue.PENDING ? '?' : result.replace(/\(.\)/, '')}
      </span>
    </div>
  );
};

export default TestTube;

import React, { useState, useEffect } from 'react';
import { Sample, GramStatus, TestType, TestResultValue, PlateObservation, TestEntry } from '../types';
import { MEDIA_TYPES, TEST_OPTIONS, MINI_GALLERIE, SMELL_OPTIONS } from '../constants';
import { analyzeBacteriologyCase } from '../services/geminiService';
import TestTube from './TestTube';
import { Plus, Trash2, Microscope, Wand2, FlaskConical, ArrowRight, Loader2, Save, Activity, CheckCircle2, Wind } from 'lucide-react';

interface WorkBenchProps {
  sample: Sample;
  onUpdateSample: (updated: Sample) => void;
}

const WorkBench: React.FC<WorkBenchProps> = ({ sample, onUpdateSample }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [activeTab, setActiveTab] = useState<'plates' | 'biochem' | 'id'>('plates');

  // Local state for forms
  const [newPlateMedia, setNewPlateMedia] = useState(MEDIA_TYPES[0]);
  const [newPlateMorph, setNewPlateMorph] = useState('');
  const [newPlateGrowth, setNewPlateGrowth] = useState<PlateObservation['growth']>('Moderate');
  const [newPlateSmell, setNewPlateSmell] = useState(SMELL_OPTIONS[0]);

  const updateGram = (status: GramStatus) => {
    onUpdateSample({ ...sample, gramStatus: status });
  };

  const addPlateObservation = () => {
    if (!newPlateMorph) return;
    const newPlate: PlateObservation = {
      id: Date.now().toString(),
      media: newPlateMedia,
      morphology: newPlateMorph,
      growth: newPlateGrowth,
      smell: newPlateSmell
    };
    onUpdateSample({ ...sample, plates: [...sample.plates, newPlate] });
    setNewPlateMorph('');
    setNewPlateSmell(SMELL_OPTIONS[0]);
  };

  const removePlate = (id: string) => {
    onUpdateSample({ ...sample, plates: sample.plates.filter(p => p.id !== id) });
  };

  const setTestResult = (type: TestType, result: TestResultValue) => {
    const existing = sample.tests.find(t => t.type === type);
    let newTests = [...sample.tests];

    if (existing) {
      newTests = newTests.map(t => t.type === type ? { ...t, result } : t);
    } else {
      newTests.push({
        id: Date.now().toString(),
        type,
        result,
        timestamp: Date.now()
      });
    }
    onUpdateSample({ ...sample, tests: newTests });
  };

  const toggleTestDetail = (type: TestType, field: 'gas' | 'h2s') => {
    const existing = sample.tests.find(t => t.type === type);
    if (!existing) {
      // Create if doesn't exist, default to first option + toggle
      const firstOption = TEST_OPTIONS[type][0];
      const newTest: TestEntry = {
        id: Date.now().toString(),
        type,
        result: firstOption,
        timestamp: Date.now(),
        [field]: true
      };
      onUpdateSample({ ...sample, tests: [...sample.tests, newTest] });
    } else {
      // Update existing
      const updatedTests = sample.tests.map(t => 
        t.type === type ? { ...t, [field]: !t[field] } : t
      );
      onUpdateSample({ ...sample, tests: updatedTests });
    }
  };

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
    const advice = await analyzeBacteriologyCase(sample);
    onUpdateSample({ ...sample, aiAnalysis: advice });
    setIsAnalyzing(false);
    setActiveTab('id'); // Switch to results tab
  };

  const handleVitekSetup = () => {
    // Check if already exists to prevent duplicates (though we could allow re-runs)
    if (sample.tests.some(t => t.type === TestType.VITEK)) return;

    const newTest: TestEntry = {
      id: Date.now().toString(),
      type: TestType.VITEK,
      result: TestResultValue.PENDING,
      timestamp: Date.now()
    };

    onUpdateSample({
      ...sample,
      status: 'Ready for ID',
      tests: [...sample.tests, newTest]
    });
  };

  const handleAPISetup = () => {
    // Determine appropriate API strip based on Gram status
    const type = sample.gramStatus === GramStatus.GPC ? TestType.API_STAPH : TestType.API_20E;

    if (sample.tests.some(t => t.type === type)) return;

    const newTest: TestEntry = {
      id: Date.now().toString(),
      type: type,
      result: TestResultValue.PENDING,
      timestamp: Date.now()
    };

    onUpdateSample({
      ...sample,
      status: 'Ready for ID',
      tests: [...sample.tests, newTest]
    });
  };

  const hasVitek = sample.tests.some(t => t.type === TestType.VITEK);
  const hasAPI = sample.tests.some(t => t.type === TestType.API_20E || t.type === TestType.API_STAPH);

  // Logic for suggesting tests
  const getSuggestedTests = () => {
    const suggestions: TestType[] = [];
    const hasTest = (t: TestType) => sample.tests.some(test => test.type === t);

    if (sample.gramStatus === GramStatus.GNB) {
      if (!hasTest(TestType.OXIDASE)) suggestions.push(TestType.OXIDASE);
      else {
        const ox = sample.tests.find(t => t.type === TestType.OXIDASE);
        if (ox?.result === TestResultValue.NEGATIVE) {
          // If Oxidase -, suggest Mini Gallerie
          MINI_GALLERIE.forEach(t => {
            if (!hasTest(t)) suggestions.push(t);
          });
        }
      }
    } else if (sample.gramStatus === GramStatus.GPC) {
      if (!hasTest(TestType.CATALASE)) suggestions.push(TestType.CATALASE);
      else {
        const cat = sample.tests.find(t => t.type === TestType.CATALASE);
        if (cat?.result === TestResultValue.POSITIVE && !hasTest(TestType.COAGULASE)) {
          suggestions.push(TestType.COAGULASE);
        }
      }
    }
    return suggestions;
  };

  const suggestedTests = getSuggestedTests();

  return (
    <div className="flex flex-col h-full bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">

      {/* Header */}
      <div className="bg-slate-50 border-b border-slate-200 p-4 flex justify-between items-center">
        <div>
          <h2 className="text-xl font-bold text-slate-800 flex items-center gap-2">
            <Microscope className="text-teal-600" />
            Workspace: <span className="font-mono text-teal-700">{sample.id}</span>
          </h2>
          <p className="text-sm text-slate-500">{sample.type} | {sample.collectionDate.split('T')[0]}</p>
        </div>
        <div className="flex space-x-2">
           <button 
             onClick={handleAIAnalysis}
