import { GoogleGenAI } from "@google/genai";
import { Sample, GramStatus, TestEntry, TestType, SampleType } from "../types";

// Initialize Gemini Client
// IMPORTANT: process.env.API_KEY must be set in the environment
const apiKey = process.env.API_KEY || ''; 
// We will handle the missing key case gracefully in the UI, but here we instantiate if present.
// If the key is empty, the calls will fail, and we catch that.

const getAiClient = () => {
    if (!apiKey) {
        throw new Error("API Key missing");
    }
    return new GoogleGenAI({ apiKey });
};

export const analyzeBacteriologyCase = async (sample: Sample, query?: string): Promise<string> => {
  try {
    const ai = getAiClient();

    // Construct a context-rich prompt
    const plateText = sample.plates.map(p => `- On ${p.media}: ${p.growth} growth. ${p.morphology}. Smell: ${p.smell || 'Not recorded'}`).join('\n');

    // Test Results
    const testText = sample.tests.length > 0 
      ? sample.tests.map(t => {
          let extra = '';
          if (t.type === TestType.KLIGLER) {
             if (t.gas) extra += ' Gas(+)';
             if (t.h2s) extra += ' H2S(+)';
          }
          return `- ${t.type}: ${t.result}${extra}`;
        }).join('\n')
      : 'No biochemical tests performed yet.';

    // Vaginal Exam Data
    let vaginalText = '';
    if (sample.type === SampleType.VAGINAL && sample.vaginalExam) {
      const v = sample.vaginalExam;
      let mycoplasmaText = 'Not Performed';
      if (v.mycoplasma.performed) {
          mycoplasmaText = `
            - M. hominis: ${v.mycoplasma.mHominis.result} (${v.mycoplasma.mHominis.titerHigh ? '>10^4' : '<10^4'})
            - U. urealyticum: ${v.mycoplasma.uUrealyticum.result} (${v.mycoplasma.uUrealyticum.titerHigh ? '>10^4' : '<10^4'})
          `;
      }

      vaginalText = `
      VAGINAL EXAM DATA:
      - Direct (Fresh):
        - Epithelial Cells: ${v.epithelialCells}
        - Leukocytes: ${v.leukocytes}
        - RBCs: ${v.redBloodCells}
        - Yeasts: ${v.yeasts}
        - Trichomonas: ${v.trichomonas}
      - Gram Stain / Flora:
        - Flora Type: ${v.floraType} (Nugent implication)
        - Doderlein (Lactobacillus): ${v.doderlein}
        - Gardnerella/Clue Cells: ${v.gardnerella}
        - Cocci +: ${v.cocciPos}
        - Cocci -: ${v.cocciNeg}
        - Intracellular GNC (Gonococcus suspect): ${v.gncIntracellular ? 'YES (Diplococci "Grains de café" Intracellular)' : 'No'}
        - BGN: ${v.bgn}
        - BGP: ${v.bgp}
      - Mycoplasma: ${mycoplasmaText}
      `;
    }

    // ECBU Exam Data
    let ecbuText = '';
    if (sample.type === SampleType.ECBU && sample.ecbuExam) {
      ecbuText = `
      ECBU CYTOLOGY:
      - Leukocytes: ${sample.ecbuExam.leukocytes || 'Not recorded'} /mm3
      - Red Blood Cells: ${sample.ecbuExam.redBloodCells || 'Not recorded'} /mm3
      `;
    }

    const systemInstruction = `
      You are an expert Clinical Microbiologist assisting a lab technician.

      Tasks:
      1. Analyze the sample data (Direct exam, Gram, Plates, Tests).
      2. For Vaginal Samples:
         - Interpret the Flora Type (Type 1 normal, Type 2 intermediate, Type 3/4 BV).
         - Comment on presence of Clue Cells/Gardnerella (BV indicator).
         - IF "Intracellular GNC" is YES: Alert for possible Neisseria gonorrhoeae and suggest confirmation.
         - For Mycoplasma/Ureaplasma: If Positive > 10^4 CFU/ml, mark as pathological. If < 10^4, typically commensal/colonization.
         - Suggest specific diagnosis (Bacterial Vaginosis, Candidiasis, Gonorrhea, Mycoplasma Infection, etc.).
      3. For Urine (ECBU) Samples:
         - Interpret the Cytology (Leukocytes & RBCs). 
         - Leukocyturia > 10^4/ml (or >10/mm3) typically indicates inflammation/infection.
         - Hematuria > 10^4/ml (or >10/mm3) may accompany infection.
         - Correlate cytology with culture growth. If Leukocytes are high but no growth, consider "Leukocyturia without bacteriuria" causes (antibiotics, TB, Chlamydia, etc.).
      4. For General Samples (Urine, Pus, etc.):
         - Suggest identification workflow based on Gram (GPC vs GNB).
         - IF GRAM NEGATIVE BACILLI (GNB): Based on colony morphology (e.g. Lactose fermentation, Swarming, Smell, Pigment), PREDICT the expected biochemical profile for the likely organism.
           Explicitly list the expected results for:
             * Oxidase (Expected result)
             * Catalase (Expected result)
             * Kligler-Hajna (Lactose/Glucose ferm, Gas, H2S)
             * Citrate Simmons (CS)
             * Mannitol Motility
             * Urea-Indole
         - IF GRAM POSITIVE COCCI (GPC): Predict Catalase and Coagulase results for likely Staph/Strep.
         - For ANY suspected organism, explicitly state the expected Catalase and Oxidase results so the user can verify them.
         - Interpret any biochemical tests already entered by the user.

      Be concise, professional, and diagnostic-oriented.
    `;

    const userPrompt = `
      Sample Type: ${sample.type}
      Gram Status (General): ${sample.gramStatus}

      ${vaginalText}
      ${ecbuText}

      Plate Observations:
      ${plateText}

      Current Test Results:
      ${testText}

      User Query: ${query || "What are the recommended follow-up tests and likely identification/diagnosis?"}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.4, 
      }
    });

    return response.text || "No analysis generated.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Unable to contact AI Advisor. Please check your network or API Key configuration.";
  }
};

export enum SampleType {
  ECBU = 'ECBU',
  VAGINAL = 'Prélèvement Vaginal',
  PUS_DEEP = 'Pus Profond',
  PUS_SUPERFICIAL = 'Pus Superficiel',
  BLOOD = 'Hémoculture',
  FLUID = 'Liquide de Ponction (LCR, Pleural...)',
  STOOL = 'Coproculture',
  OTHER = 'Autre'
}

export enum GramStatus {
  UNKNOWN = 'Unknown',
  GPC = 'Gram Positive Cocci',
  GNB = 'Gram Negative Bacilli',
  GPB = 'Gram Positive Bacilli',
  GNC = 'Gram Negative Cocci',
  YEAST = 'Yeast'
}

export enum Quantity {
  ABSENT = 'Absent',
  RARE = 'Rare',
  FEW = 'Assez nombreux',
  MANY = 'Nombreux',
  VERY_MANY = 'Très nombreux'
}

export interface MycoplasmaResult {
  result: 'Positive' | 'Negative';
  titerHigh: boolean; // true if >= 10^4 CFU/ml
}

export interface VaginalExam {
  // Direct Microscope
  epithelialCells: Quantity;
  leukocytes: Quantity;
  redBloodCells: Quantity;
  yeasts: Quantity;
  trichomonas: Quantity;

  // Gram / Flora
  floraType: 'Type 1' | 'Type 2' | 'Type 3' | 'Type 4';
  doderlein: Quantity;
  gardnerella: Quantity; // "G. vaginalis (mobiluncus, clue cells)"

  // Other Bacteria
  cocciPos: Quantity;
  cocciNeg: Quantity;
  gncIntracellular: boolean; // "Grain de café" intracellular check
  bgn: Quantity;
  bgp: Quantity;

  // Mycoplasma
  mycoplasma: {
    performed: boolean;
    mHominis: MycoplasmaResult;
    uUrealyticum: MycoplasmaResult;
  };
}

export interface ECBUExam {
  leukocytes: string; // Count per mm3
  redBloodCells: string; // Count per mm3
}

export enum TestType {
  CATALASE = 'Catalase',
  COAGULASE = 'Coagulase',
  OXIDASE = 'Oxidase',
  KLIGLER = 'Kligler (Glu/Lac/Gas/H2S)',
  MANNITOL = 'Mannitol Motility',
  UREA_INDOLE = 'Urea-Indole',
  CITRATE = 'Citrate (Simmons)',
  VITEK = 'Vitek Automaton',
  API_20E = 'API 20E',
  API_STAPH = 'API Staph'
}

export enum TestResultValue {
