import { GoogleGenAI, SchemaType } from "@google/genai";
import { Sample, GramStatus, TestEntry, TestType, SampleType, GermKnowledge } from "../types";

// Initialize Gemini Client
// IMPORTANT: process.env.API_KEY must be set in the environment
const apiKey = process.env.API_KEY || ''; 
// We will handle the missing key case gracefully in the UI, but here we instantiate if present.
// If the key is empty, the calls will fail, and we catch that.

const getAiClient = () => {
    if (!apiKey) {
        throw new Error("API Key missing");
    }
    return new GoogleGenAI({ apiKey });
};

export const analyzeBacteriologyCase = async (sample: Sample, query?: string): Promise<string> => {
  try {
    const ai = getAiClient();

    // Construct a context-rich prompt
    const plateText = sample.plates.map(p => `- On ${p.media}: ${p.growth} growth. ${p.morphology}. Smell: ${p.smell || 'Not recorded'}`).join('\n');

    // Test Results
    const testText = sample.tests.length > 0 
      ? sample.tests.map(t => {
          let extra = '';
          if (t.type === TestType.KLIGLER) {
             if (t.gas) extra += ' Gas(+)';
             if (t.h2s) extra += ' H2S(+)';
          }
          if (t.type === TestType.MANNITOL) {
             if (t.motility) extra += ' Motility(+)';
          }
          return `- ${t.type}: ${t.result}${extra}`;
        }).join('\n')
      : 'No biochemical tests performed yet.';

    // Vaginal Exam Data
    let vaginalText = '';
    if (sample.type === SampleType.VAGINAL && sample.vaginalExam) {
      const v = sample.vaginalExam;
      let mycoplasmaText = 'Not Performed';
      if (v.mycoplasma.performed) {
          mycoplasmaText = `
            - M. hominis: ${v.mycoplasma.mHominis.result} (${v.mycoplasma.mHominis.titerHigh ? '>10^4' : '<10^4'})
            - U. urealyticum: ${v.mycoplasma.uUrealyticum.result} (${v.mycoplasma.uUrealyticum.titerHigh ? '>10^4' : '<10^4'})
          `;
      }

      vaginalText = `
      VAGINAL EXAM DATA:
      - Direct (Fresh):
        - Epithelial Cells: ${v.epithelialCells}
        - Leukocytes: ${v.leukocytes}
        - RBCs: ${v.redBloodCells}
        - Yeasts: ${v.yeasts}
        - Trichomonas: ${v.trichomonas}
      - Gram Stain / Flora:
        - Flora Type: ${v.floraType} (Nugent implication)
        - Doderlein (Lactobacillus): ${v.doderlein}
        - Gardnerella/Clue Cells: ${v.gardnerella}
        - Cocci +: ${v.cocciPos}
        - Cocci -: ${v.cocciNeg}
        - Intracellular GNC (Gonococcus suspect): ${v.gncIntracellular ? 'YES (Diplococci "Grains de café" Intracellular)' : 'No'}
        - BGN: ${v.bgn}
        - BGP: ${v.bgp}
      - Mycoplasma: ${mycoplasmaText}
      `;
    }

    // ECBU Exam Data
    let ecbuText = '';
    if (sample.type === SampleType.ECBU && sample.ecbuExam) {
      ecbuText = `
      ECBU CYTOLOGY:
      - Leukocytes: ${sample.ecbuExam.leukocytes || 'Not recorded'} /mm3
      - Red Blood Cells: ${sample.ecbuExam.redBloodCells || 'Not recorded'} /mm3
      `;
    }

    const systemInstruction = `
      You are an expert Clinical Microbiologist assisting a lab technician.

      Tasks:
      1. Analyze the sample data (Direct exam, Gram, Plates, Tests).
      2. For Vaginal Samples:
         - Interpret the Flora Type (Type 1 normal, Type 2 intermediate, Type 3/4 BV).
         - Comment on presence of Clue Cells/Gardnerella (BV indicator).
         - IF "Intracellular GNC" is YES: Alert for possible Neisseria gonorrhoeae and suggest confirmation.
         - For Mycoplasma/Ureaplasma: If Positive > 10^4 CFU/ml, mark as pathological. If < 10^4, typically commensal/colonization.
         - Suggest specific diagnosis (Bacterial Vaginosis, Candidiasis, Gonorrhea, Mycoplasma Infection, etc.).
      3. For Urine (ECBU) Samples:
         - Interpret the Cytology (Leukocytes & RBCs). 
         - Leukocyturia > 10^4/ml (or >10/mm3) typically indicates inflammation/infection.
         - Hematuria > 10^4/ml (or >10/mm3) may accompany infection.
         - Correlate cytology with culture growth. If Leukocytes are high but no growth, consider "Leukocyturia without bacteriuria" causes (antibiotics, TB, Chlamydia, etc.).
      4. For General Samples (Urine, Pus, etc.):
         - Suggest identification workflow based on Gram (GPC vs GNB).
         - IF GRAM NEGATIVE BACILLI (GNB): Based on colony morphology (e.g. Lactose fermentation, Swarming, Smell, Pigment), PREDICT the expected biochemical profile for the likely organism.
           Explicitly list the expected results for:
             * Oxidase (Expected result)
             * Catalase (Expected result)
             * Kligler-Hajna (Lactose/Glucose ferm, Gas, H2S)
             * Citrate Simmons (CS)
             * Mannitol Motility (Fermentation & Motility)
             * Urea-Indole
         - IF GRAM POSITIVE COCCI (GPC): Predict Catalase and Coagulase results for likely Staph/Strep.
         - For ANY suspected organism, explicitly state the expected Catalase and Oxidase results so the user can verify them.
         - Interpret any biochemical tests already entered by the user.

      Be concise, professional, and diagnostic-oriented.
    `;

    const userPrompt = `
      Sample Type: ${sample.type}
      Gram Status (General): ${sample.gramStatus}

      ${vaginalText}
      ${ecbuText}

      Plate Observations:
      ${plateText}

      Current Test Results:
      ${testText}

      User Query: ${query || "What are the recommended follow-up tests and likely identification/diagnosis?"}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.4, 
      }
    });

    return response.text || "No analysis generated.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Unable to contact AI Advisor. Please check your network or API Key configuration.";
  }
};

export const getGermKnowledge = async (germName: string): Promise<GermKnowledge> => {
  try {
    const ai = getAiClient();
    const prompt = `Provide the expected biochemical test results for the bacteria "${germName}".
    Return the result in strict JSON format.
    Fields required:
    - name: string (Full scientific name)
    - family: string (e.g. Enterobacteriaceae)
    - gram: string (e.g. GNB or GPC)
    - catalase: string (+ or -)
    - oxidase: string (+ or -)
    - coagulase: string (+ or - or NA)
    - mannitol: string (+ or -)
    - motility: string (+ or -)
    - citrate: string (+ or -)
    - urea: string (+ or -)
    - indole: string (+ or -)
    - kligler: string (e.g. "Acid/Acid Gas+ H2S-" or "K/A No Gas")
    - notes: string (Any specific characteristics like smell, swarming, pigment)

    If the germ is unknown, return "Unknown" in the name field.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as GermKnowledge;
    }
    throw new Error("Empty response");

  } catch (error) {
    console.error("Gemini Reference Error:", error);
    throw error;
  }
};

import React from 'react';
import { TestType, TestResultValue } from '../types';

interface TestTubeProps {
  type: TestType;
  result: TestResultValue;
  onClick: () => void;
  gas?: boolean;
  h2s?: boolean;
  motility?: boolean;
}

const TestTube: React.FC<TestTubeProps> = ({ type, result, onClick, gas, h2s, motility }) => {

  const getColors = () => {
    if (result === TestResultValue.PENDING) return 'bg-gray-200 border-gray-300 text-gray-400';

    // Kligler Logic
    if (type === TestType.KLIGLER) {
      let fromColor = '';
      let toColor = '';
      let borderColor = 'border-red-600';
      let textColor = 'text-white';

      // Top (Slant)
      if (result === TestResultValue.ACID_ACID) {
        fromColor = 'from-yellow-400';
        borderColor = 'border-yellow-500';
        textColor = 'text-yellow-900';
      } else if (result === TestResultValue.ALK_ACID || result === TestResultValue.ALK_ALK) {
        fromColor = 'from-red-500';
      } else {
        // Pending or invalid
        return 'bg-gray-200 border-gray-300 text-gray-400';
      }

      // Bottom (Butt)
      if (h2s) {
        toColor = 'to-slate-900'; // Black for H2S
        textColor = 'text-white'; // Ensure text is visible on black
      } else {
        if (result === TestResultValue.ACID_ACID || result === TestResultValue.ALK_ACID) {
          toColor = 'to-yellow-400';
        } else {
          toColor = 'to-red-500';
        }
      }

      // Override text color if A/A and no H2S (Yellow background needs dark text)
      if (result === TestResultValue.ACID_ACID && !h2s) {
        textColor = 'text-yellow-900';
      }

      return `bg-gradient-to-b ${fromColor} ${toColor} ${borderColor} ${textColor}`;
    }

    // Urea Indole
    if (type === TestType.UREA_INDOLE) {
      if (result === TestResultValue.POSITIVE) return 'bg-pink-500 border-pink-600 text-white'; // Urease +
      if (result === TestResultValue.NEGATIVE) return 'bg-yellow-100 border-yellow-300 text-yellow-800'; // Urease -
    }

    // Citrate
    if (type === TestType.CITRATE) {
      if (result === TestResultValue.POSITIVE) return 'bg-blue-600 border-blue-700 text-white'; // Citrate + (Blue)
      if (result === TestResultValue.NEGATIVE) return 'bg-green-500 border-green-600 text-white'; // Citrate - (Green)
    }

    // Standard Positive/Negative for others
    if (result === TestResultValue.POSITIVE) return 'bg-teal-500 border-teal-600 text-white';
    if (result === TestResultValue.NEGATIVE) return 'bg-rose-100 border-rose-300 text-rose-800';

    return 'bg-slate-100 border-slate-300 text-slate-600';
  };

  return (
    <div 
      onClick={onClick}
      className={`relative h-24 w-16 rounded-b-2xl rounded-t-md border-2 flex flex-col items-center justify-end p-2 cursor-pointer transition-transform hover:scale-105 shadow-sm ${getColors()}`}
    >
      <div className="absolute top-[-10px] w-full text-center">
         <span className="text-[10px] uppercase font-bold tracking-tighter text-slate-500 bg-white/80 px-1 rounded shadow-sm border border-slate-200">
          {type.split(' ')[0]}
         </span>
      </div>

      {/* Visual Indicators for Gas and H2S */}
      {gas && (
        <div className="absolute top-8 right-1 bg-white/30 backdrop-blur-sm rounded-full w-5 h-5 flex items-center justify-center border border-white/50 shadow-sm z-20" title="Gas Production">
          <span className="text-[9px] font-bold">G</span>
        </div>
      )}

      {h2s && (
        <div className="absolute bottom-6 left-1 text-[8px] font-bold text-white/90 bg-black/20 px-1 rounded z-20" title="H2S Production">
          H2S
        </div>
      )}

      {motility && (
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 text-[9px] font-bold text-slate-700 bg-white/60 px-1 rounded shadow-sm border border-slate-300 z-20" title="Motility Positive">
          MOT+
        </div>
      )}

      <span className="text-xs font-bold text-center leading-tight z-10">
        {result === TestResultValue.PENDING ? '?' : result.replace(/\(.\)/, '')}
      </span>
    </div>
  );
};

