        )}

        {!data && !loading && !error && (
          <div className="flex-1 flex flex-col items-center justify-center text-slate-300">
            <Dna className="w-32 h-32 mb-4 opacity-20" />
            <p className="text-sm font-medium">Search for a bacteria to see details</p>
          </div>
        )}
      </div>
    </div>
  );
};

