  cocciPos: Quantity;
  cocciNeg: Quantity;
  gncIntracellular: boolean; // "Grain de café" intracellular check
  bgn: Quantity;
  bgp: Quantity;

  // Mycoplasma
  mycoplasma: {
    performed: boolean;
    mHominis: MycoplasmaResult;
    uUrealyticum: MycoplasmaResult;
  };
}

export interface ECBUExam {
