import { GoogleGenAI, SchemaType } from "@google/genai";
import { Sample, GramStatus, TestEntry, TestType, SampleType, GermKnowledge } from "../types";

// Initialize Gemini Client
// IMPORTANT: process.env.API_KEY must be set in the environment
const apiKey = process.env.API_KEY || ''; 
// We will handle the missing key case gracefully in the UI, but here we instantiate if present.
// If the key is empty, the calls will fail, and we catch that.

const getAiClient = () => {
    if (!apiKey) {
        throw new Error("API Key missing");
    }
    return new GoogleGenAI({ apiKey });
};

export const analyzeBacteriologyCase = async (sample: Sample, query?: string): Promise<string> => {
  try {
    const ai = getAiClient();

    // Construct a context-rich prompt
    const plateText = sample.plates.map(p => `- On ${p.media}: ${p.growth} growth. ${p.morphology}. Smell: ${p.smell || 'Not recorded'}`).join('\n');

    // Test Results
    const testText = sample.tests.length > 0 
      ? sample.tests.map(t => {
          let extra = '';
          if (t.type === TestType.KLIGLER) {
             if (t.gas) extra += ' Gas(+)';
             if (t.h2s) extra += ' H2S(+)';
          }
          if (t.type === TestType.MANNITOL) {
             if (t.motility) extra += ' Motility(+)';
          }
          return `- ${t.type}: ${t.result}${extra}`;
        }).join('\n')
      : 'No biochemical tests performed yet.';

    // Vaginal Exam Data
    let vaginalText = '';
    if (sample.type === SampleType.VAGINAL && sample.vaginalExam) {
      const v = sample.vaginalExam;
      let mycoplasmaText = 'Not Performed';
      if (v.mycoplasma.performed) {
          mycoplasmaText = `
            - M. hominis: ${v.mycoplasma.mHominis.result} (${v.mycoplasma.mHominis.titerHigh ? '>10^4' : '<10^4'})
            - U. urealyticum: ${v.mycoplasma.uUrealyticum.result} (${v.mycoplasma.uUrealyticum.titerHigh ? '>10^4' : '<10^4'})
          `;
      }

      vaginalText = `
      VAGINAL EXAM DATA:
      - Direct (Fresh):
        - Epithelial Cells: ${v.epithelialCells}
        - Leukocytes: ${v.leukocytes}
        - RBCs: ${v.redBloodCells}
        - Yeasts: ${v.yeasts}
        - Trichomonas: ${v.trichomonas}
      - Gram Stain / Flora:
        - Flora Type: ${v.floraType} (Nugent implication)
        - Doderlein (Lactobacillus): ${v.doderlein}
        - Gardnerella/Clue Cells: ${v.gardnerella}
        - Cocci +: ${v.cocciPos}
        - Cocci -: ${v.cocciNeg}
        - Intracellular GNC (Gonococcus suspect): ${v.gncIntracellular ? 'YES (Diplococci "Grains de café" Intracellular)' : 'No'}
        - BGN: ${v.bgn}
        - BGP: ${v.bgp}
      - Mycoplasma: ${mycoplasmaText}
      `;
    }

    // ECBU Exam Data
    let ecbuText = '';
    if (sample.type === SampleType.ECBU && sample.ecbuExam) {
      ecbuText = `
      ECBU CYTOLOGY:
      - Leukocytes: ${sample.ecbuExam.leukocytes || 'Not recorded'} /mm3
      - Red Blood Cells: ${sample.ecbuExam.redBloodCells || 'Not recorded'} /mm3
      `;
    }

    const systemInstruction = `
      You are an expert Clinical Microbiologist assisting a lab technician.

      Tasks:
      1. Analyze the sample data (Direct exam, Gram, Plates, Tests).

      2. APPLY SPECIFIC IDENTIFICATION PROTOCOLS:

         A. GRAM POSITIVE COCCI (GPC):
            - First Step: CATALASE.
            - If CATALASE POSITIVE -> Staphylococcus.
              * Check COAGULASE.
              * Coagulase (+): Staphylococcus aureus.
              * Coagulase (-): Check NOVOBIOCIN.
                - Novobiocin Sensitive: Staphylococcus epidermidis.
                - Novobiocin Resistant: Staphylococcus saprophyticus.
              * S. aureus typically Mannitol (+). S. epidermidis Mannitol (-). S. saprophyticus Mannitol (+) variable.

            - If CATALASE NEGATIVE -> Streptococcus / Enterococcus.
              * Check HEMOLYSIS on Blood Agar.
              * ALPHA Hemolysis (Green): 
                - Check OPTOCHIN (Taxo P). Sensitive = S. pneumoniae. Resistant = Viridans Strep (S. mitis, S. mutans, etc).
                - Check Bile Solubility (Pneumo +, Viridans -).
              * BETA Hemolysis (Clear):
                - Check BACITRACIN (Taxo A). Sensitive = Group A (S. pyogenes). Resistant = Check CAMP/SXT.
                - CAMP Positive = Group B (S. agalactiae).
                - SXT Sensitive = Group C (S. equi, etc).
              * GAMMA (No Hemolysis) or Alpha:
                - Check BILE ESCULIN. Positive = Group D (Enterococcus or S. bovis).
                - Differentiate Group D: NaCl 6.5%. Growth (+) = Enterococcus faecalis/faecium. No Growth (-) = S. bovis.

         B. GRAM NEGATIVE BACILLI (GNB):
            - First Step: OXIDASE.
            - If OXIDASE POSITIVE: Pseudomonas (Green pigment, fruity smell), Alcaligenes, etc.
            - If OXIDASE NEGATIVE: Enterobacteriaceae.
            - Use Kligler Iron Agar (KIA) pattern:
              * Red/Yellow (K/A) = Glucose only (Shigella, Salmonella, Proteus). Check H2S.
              * Yellow/Yellow (A/A) = Glucose + Lactose (E. coli, Klebsiella, Enterobacter).
            - Key differentiations:
              * Proteus: Urea (++), TDA (+), H2S (+), Swarming.
              * E. coli: Indole (+), Citrate (-), Lactose (+).
              * Klebsiella: Non-motile, Citrate (+), Indole (- usually), Mucoid colonies.
              * Enterobacter: Motile, Citrate (+), Indole (-).
              * Salmonella: H2S (+), Citrate (+), Urea (-).
              * Shigella: H2S (-), Motility (-), Urea (-).

      3. For Vaginal Samples:
         - Interpret the Flora Type (Type 1 normal, Type 2 intermediate, Type 3/4 BV).
         - Comment on presence of Clue Cells/Gardnerella (BV indicator).
         - IF "Intracellular GNC" is YES: Alert for possible Neisseria gonorrhoeae.
         - Mycoplasma thresholds (>10^4 pathogenic).

      4. For Urine (ECBU):
         - Leukocyturia/Hematuria significance.
         - Correlation with culture.

      5. ANTIBIOGRAM & RESISTANCE RESEARCH (CRITICAL):
         - For Staphylococcus: Suggest testing Cefoxitin (screen for MRSA).
         - For Enterobacteriaceae: Suggest looking for ESBL (Synergy Augmentin+C3G).
         - For Streptococcus: Suggest screening with Oxacillin (Pneumococcus).
         - For Enterococcus: High-Level Aminoglycosides.
         - For Pseudomonas: Warn about MDR.

      Be concise, professional, and diagnostic-oriented. Provide the likely ID and the reasoning based on the tests provided.
    `;

    const userPrompt = `
      Sample Type: ${sample.type}
      Gram Status (General): ${sample.gramStatus}

      ${vaginalText}
      ${ecbuText}

      Plate Observations:
      ${plateText}

      Current Test Results:
      ${testText}

      User Query: ${query || "What are the recommended follow-up tests, likely identification, and antibiotic resistance orientation?"}
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: userPrompt,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.4, 
      }
    });

    return response.text || "No analysis generated.";
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Unable to contact AI Advisor. Please check your network or API Key configuration.";
  }
};

export const getGermKnowledge = async (germName: string): Promise<GermKnowledge> => {
  try {
    const ai = getAiClient();
    const prompt = `Provide the expected biochemical test results for the bacteria "${germName}".
    Return the result in strict JSON format.
    Fields required:
    - name: string (Full scientific name)
    - family: string (e.g. Enterobacteriaceae)
    - gram: string (e.g. GNB or GPC)
    - catalase: string (+ or -)
    - oxidase: string (+ or -)
    - coagulase: string (+ or - or NA)
    - mannitol: string (+ or -)
    - motility: string (+ or -)
    - citrate: string (+ or -)
    - urea: string (+ or -)
    - indole: string (+ or -)
    - tda: string (+ or -)
    - kligler: string (e.g. "Acid/Acid Gas+ H2S-" or "K/A No Gas")
    - notes: string (Any specific characteristics like smell, swarming, pigment)

    If the germ is unknown, return "Unknown" in the name field.
    `;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: 'application/json',
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as GermKnowledge;
    }
    throw new Error("Empty response");

  } catch (error) {
    console.error("Gemini Reference Error:", error);
    throw error;
  }
};

import React, { useState, useEffect } from 'react';
import { Sample, GramStatus, TestType, TestResultValue, PlateObservation, TestEntry, SampleType, VaginalExam, ECBUExam } from '../types';
import { MEDIA_TYPES, TEST_OPTIONS, MINI_GALLERIE, SMELL_OPTIONS, QUANTITY_OPTIONS, FLORA_TYPE_OPTIONS, DEFAULT_VAGINAL_EXAM, DEFAULT_ECBU_EXAM } from '../constants';
import { analyzeBacteriologyCase } from '../services/geminiService';
import TestTube from './TestTube';
import { Plus, Trash2, Microscope, Wand2, FlaskConical, ArrowRight, Loader2, Save, Activity, CheckCircle2, Wind, Beaker, TestTube2, AlertCircle, Droplets } from 'lucide-react';

interface WorkBenchProps {
  sample: Sample;
  onUpdateSample: (updated: Sample) => void;
}

const WorkBench: React.FC<WorkBenchProps> = ({ sample, onUpdateSample }) => {
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [activeTab, setActiveTab] = useState<'plates' | 'biochem' | 'id'>('plates');

  // Local state for forms
  const [newPlateMedia, setNewPlateMedia] = useState(MEDIA_TYPES[0]);
  const [newPlateMorph, setNewPlateMorph] = useState('');
  const [newPlateGrowth, setNewPlateGrowth] = useState<PlateObservation['growth']>('Moderate');
  const [newPlateSmell, setNewPlateSmell] = useState(SMELL_OPTIONS[0]);

  const updateGram = (status: GramStatus) => {
    onUpdateSample({ ...sample, gramStatus: status });
  };

  const updateSampleType = (newType: SampleType) => {
     let updated = { ...sample, type: newType };
     // Initialize specific exam data if missing
     if (newType === SampleType.VAGINAL && !updated.vaginalExam) {
       updated.vaginalExam = { ...DEFAULT_VAGINAL_EXAM };
     }
     if (newType === SampleType.ECBU && !updated.ecbuExam) {
       updated.ecbuExam = { ...DEFAULT_ECBU_EXAM };
     }
     onUpdateSample(updated);
  };

  const updateVaginalExam = (field: keyof VaginalExam, value: any) => {
    if (!sample.vaginalExam) return;
    onUpdateSample({
      ...sample,
      vaginalExam: {
        ...sample.vaginalExam,
        [field]: value
      }
    });
  };

  const updateECBUExam = (field: keyof ECBUExam, value: string) => {
    if (!sample.ecbuExam) return;
    onUpdateSample({
      ...sample,
      ecbuExam: {
        ...sample.ecbuExam,
        [field]: value
      }
    });
  };

  const updateMycoplasma = (germ: 'mHominis' | 'uUrealyticum', field: 'result' | 'titerHigh', value: any) => {
    if (!sample.vaginalExam) return;
    onUpdateSample({
      ...sample,
      vaginalExam: {
        ...sample.vaginalExam,
        mycoplasma: {
          ...sample.vaginalExam.mycoplasma,
          [germ]: {
            ...sample.vaginalExam.mycoplasma[germ],
            [field]: value
          }
        }
      }
    });
  };

  const toggleMycoplasmaPerformed = () => {
    if (!sample.vaginalExam) return;
    onUpdateSample({
      ...sample,
      vaginalExam: {
        ...sample.vaginalExam,
        mycoplasma: {
          ...sample.vaginalExam.mycoplasma,
          performed: !sample.vaginalExam.mycoplasma.performed
        }
      }
    });
  };


  const addPlateObservation = () => {
    const newPlate: PlateObservation = {
      id: Date.now().toString(),
      media: newPlateMedia,
      morphology: newPlateMorph || 'No description provided',
      growth: newPlateGrowth,
      smell: newPlateSmell
    };
    onUpdateSample({ ...sample, plates: [...sample.plates, newPlate] });
    setNewPlateMorph('');
    setNewPlateSmell(SMELL_OPTIONS[0]);
  };

  const removePlate = (id: string) => {
    onUpdateSample({ ...sample, plates: sample.plates.filter(p => p.id !== id) });
  };

  const setTestResult = (type: TestType, result: TestResultValue) => {
    const existing = sample.tests.find(t => t.type === type);
    let newTests = [...sample.tests];

    if (existing) {
      newTests = newTests.map(t => t.type === type ? { ...t, result } : t);
    } else {
      newTests.push({
        id: Date.now().toString(),
        type,
        result,
        timestamp: Date.now()
      });
    }
    onUpdateSample({ ...sample, tests: newTests });
  };

  const toggleTestDetail = (type: TestType, field: 'gas' | 'h2s' | 'motility') => {
    const existing = sample.tests.find(t => t.type === type);
    if (!existing) {
      // Create if doesn't exist, default to first option + toggle
      const firstOption = TEST_OPTIONS[type][0];
      const newTest: TestEntry = {
        id: Date.now().toString(),
        type,
        result: firstOption,
        timestamp: Date.now(),
        [field]: true
      };
      onUpdateSample({ ...sample, tests: [...sample.tests, newTest] });
    } else {
      // Update existing
      const updatedTests = sample.tests.map(t => 
        t.type === type ? { ...t, [field]: !t[field] } : t
      );
      onUpdateSample({ ...sample, tests: updatedTests });
    }
  };

  const handleAIAnalysis = async () => {
    setIsAnalyzing(true);
    const advice = await analyzeBacteriologyCase(sample);
    onUpdateSample({ ...sample, aiAnalysis: advice });
    setIsAnalyzing(false);
    setActiveTab('id'); // Switch to results tab
  };

  const handleVitekSetup = () => {
    if (sample.tests.some(t => t.type === TestType.VITEK)) return;

    const newTest: TestEntry = {
      id: Date.now().toString(),
      type: TestType.VITEK,
      result: TestResultValue.PENDING,
      timestamp: Date.now()
    };

    onUpdateSample({
      ...sample,
      status: 'Ready for ID',
      tests: [...sample.tests, newTest]
    });
  };

  const handleAPISetup = () => {
    const type = sample.gramStatus === GramStatus.GPC ? TestType.API_STAPH : TestType.API_20E;
    if (sample.tests.some(t => t.type === type)) return;

    const newTest: TestEntry = {
      id: Date.now().toString(),
      type: type,
      result: TestResultValue.PENDING,
      timestamp: Date.now()
    };

    onUpdateSample({
      ...sample,
      status: 'Ready for ID',
      tests: [...sample.tests, newTest]
    });
  };

  const hasVitek = sample.tests.some(t => t.type === TestType.VITEK);
  const hasAPI = sample.tests.some(t => t.type === TestType.API_20E || t.type === TestType.API_STAPH);

  const getSuggestedTests = () => {
    const suggestions: TestType[] = [];
    const hasTest = (t: TestType) => sample.tests.some(test => test.type === t);

    // Initial logic based on Gram Status
    if (sample.gramStatus === GramStatus.GNB) {
      if (!hasTest(TestType.OXIDASE)) suggestions.push(TestType.OXIDASE);
      else {
        // If Oxidase Negative -> Enterobacteriaceae logic
        const ox = sample.tests.find(t => t.type === TestType.OXIDASE);
        if (ox?.result === TestResultValue.NEGATIVE) {
          MINI_GALLERIE.forEach(t => {
            if (!hasTest(t)) suggestions.push(t);
          });
        }
      }
    } else if (sample.gramStatus === GramStatus.GPC) {
      if (!hasTest(TestType.CATALASE)) suggestions.push(TestType.CATALASE);
      else {
        const cat = sample.tests.find(t => t.type === TestType.CATALASE);

        if (cat?.result === TestResultValue.POSITIVE) {
           // Staphylococcus Pathway
           if (!hasTest(TestType.COAGULASE)) suggestions.push(TestType.COAGULASE);
           const coag = sample.tests.find(t => t.type === TestType.COAGULASE);
           // If Coagulase Negative -> Check Novobiocin for S. sapro vs S. epidermidis
           if (coag?.result === TestResultValue.NEGATIVE && !hasTest(TestType.NOVOBIOCIN)) {
              suggestions.push(TestType.NOVOBIOCIN);
           }
        } else if (cat?.result === TestResultValue.NEGATIVE) {
           // Streptococcus Pathway
           // We can't easily know hemolysis from here structurally, so suggest the panel
           if (!hasTest(TestType.OPTOCHIN)) suggestions.push(TestType.OPTOCHIN);
           if (!hasTest(TestType.BACITRACIN)) suggestions.push(TestType.BACITRACIN);
           if (!hasTest(TestType.CAMP)) suggestions.push(TestType.CAMP);
           if (!hasTest(TestType.BILE_ESCULIN)) suggestions.push(TestType.BILE_ESCULIN);
           if (!hasTest(TestType.NACL_6_5)) suggestions.push(TestType.NACL_6_5);
        }
      }
    }
    return suggestions;
  };

  const suggestedTests = getSuggestedTests();

  // Helper for rendering Quantity Selects
  const renderQuantitySelect = (label: string, field: keyof VaginalExam, isBold = false) => (
    <div className="flex flex-col gap-1">
      <label className={`text-xs ${isBold ? 'font-bold text-slate-800' : 'text-slate-600'}`}>{label}</label>
      <select 
        value={sample.vaginalExam?.[field] || ''} 
        onChange={(e) => updateVaginalExam(field, e.target.value)}
